require('dotenv').config();

let globalSessionManager = null;

module.exports = function(RED) {
  const SessionManager = require('kumva-insights/utils/session-manager');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');
  const WebhookManager = require('kumva-insights/utils/webhook-manager');
  const AfricasTalkingService = require('kumva-insights/utils/africastalking');

  function createSessionKey(serviceType, phoneNumber, callerIdOrShortCode) {
    if (!serviceType || !phoneNumber || !callerIdOrShortCode) {
      throw new Error('Missing required parameters to create session key');
    }
    const parts = [serviceType, phoneNumber, callerIdOrShortCode].filter(p => p);
    return parts.join(':');
  }

  async function initializeGlobals() {
    if (!globalSessionManager) {
      const configManager = new ConfigManager();
      globalSessionManager = new SessionManager(configManager.getRedisConfig());
      await globalSessionManager.initialize();
    }
    return { sessionManager: globalSessionManager };
  }

  // Holds the live Express `res` object for a voice session while we wait for
  // the flow (Send Message / End Flow) to decide what to say back to Africa's
  // Talking. Lives in global context so it's shared across all Kumva nodes,
  // same pattern as the shared sessionManager below. Never touched for SMS.
  function getPendingVoiceResponses(node) {
    let map = node.context().global.get('kumvaPendingVoiceResponses');
    if (!map) {
      map = new Map();
      node.context().global.set('kumvaPendingVoiceResponses', map);
    }
    return map;
  }

  function KumvaStartCampaignNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;
    const flowId = this.z;
    const initiationMode = config.initiationMode || 'outbound';
    const campaignType = config.campaignType || 'sms';
    const webhookPath = config.webhookPath || '/kumva/webhook';
    const baseUrl = process.env.KUMVA_WEBHOOK_BASE_URL;
    const webhookUrl = `${String(baseUrl).replace(/\/$/, '')}${webhookPath}`;

    initializeGlobals().then(({ sessionManager }) => {
      node.context().global.set('sessionManager', sessionManager);
    });

    node.context().flow.set('initiationMode', initiationMode);

    if (!node.context().global.get('registeredWebhookPaths')) {
      node.context().global.set('registeredWebhookPaths', new Map());
    }

    const pendingVoiceResponses = getPendingVoiceResponses(node);

    function registerWebhookEndpoint(campaignId) {
      // todo: handle webhook registration differently. first verify if it exists and associated with an active flow. if not continue execution else warn of collision
      const existingRegistration = node.context().global.get('registeredWebhookPaths').get(webhookPath);
      if (existingRegistration) {
        if (existingRegistration.campaignId !== campaignId) {
          throw new Error(`Webhook path "${webhookPath}" is already registered. Choose a unique webhook path.`);
        }
      } else {
        node.context().global.get('registeredWebhookPaths').set(webhookPath, { webhookPath, flowId, campaignId });
      }

      if (!RED.httpNode._kumvaWebhooks) RED.httpNode._kumvaWebhooks = new Map();
      if (RED.httpNode._kumvaWebhooks.has(webhookPath)) {
        return;
      }

      RED.httpNode._kumvaWebhooks.set(webhookPath, true);

      RED.httpNode.post(webhookPath, async (req, res) => {
        try {
          const payload = req.body || {};
          const webhookMgr = new WebhookManager();
          const response = webhookMgr.parseAfricasTalkingPayload(payload);

          if (!response) {
            console.log('parsing africastalking payload failed. payload: ', payload);
            return res.status(400).json({ success: false, error: 'Unable to parse payload' });
          }

          const sessionManager = node.context().global.get('sessionManager');
          const currentInitiationMode = node.context().flow.get('initiationMode');

          // IVR
          if (response.type === 'sms') {
            const serviceType = 'sms';
            const phoneNumber = response.phoneNumber;
            const sessionKey = createSessionKey(serviceType, phoneNumber, config?.callerId || config?.shortCode);

            const sessionResult = await sessionManager.getSession(sessionKey);

            if (!sessionResult?.exists) {
              if (currentInitiationMode !== 'inbound') {
                return res.json({ success: false, error: 'No active session found. Not an Inbound service' });
              }
              await sessionManager.createSession(sessionKey, {
                sessionKey,
                campaignId,
                phoneNumber,
                serviceType,
                status: 'active',
                source: 'webhook',
                sessionIdentity: response.sessionIdentity || phoneNumber || response.sessionId,
                currentWaitingNode: null,
                createdAt: new Date().toISOString(),
                lastUpdated: new Date().toISOString()
              }, config.sessionTimeout ? helpers.timeToSeconds(config.sessionTimeout) : 3600);

              node.send({ ...response, campaignId, sessionKey, _kumva: { campaignId, webhookPath, sessionKey } });
              return res.json({ success: true, sessionKey, campaignId });
            }

            const sessionData = sessionResult.data;
            const waitingNodeData = sessionData?.currentWaitingNode;

            if (waitingNodeData?.nodeId) {
              const targetNode = RED.nodes.getNode(waitingNodeData.nodeId);
              if (targetNode) {
                targetNode.receive({
                  response,
                  isFromWebhook: true,
                  campaignId,
                  sessionKey,
                  phoneNumber: sessionData.phoneNumber,
                  callerId: sessionData.callerId,
                  shortCode: sessionData.shortCode,
                });
                console.log('sending response to wait for response: ', response);
              } else {
                return res.status(400).json({ success: false, error: 'Waiting node not found', sessionKey, campaignId, nodeId: waitingNodeData.nodeId });
              }
            } else {
              return res.status(400).json({ success: false, error: 'Waiting node id not found in session data', sessionKey, campaignId });
            }
            return res.json({ success: true, sessionKey, campaignId, webhookPath });
          }

          // IVR
          if (response.type === 'ivr') {
            return await handleVoiceWebhook(response, res, sessionManager, currentInitiationMode);
          }

          return res.status(400).json({ success: false, error: 'Unrecognized payload type' });
        } catch (error) {
          console.error('[KUMVA][StartCampaign] webhook-error', error);
          return res.status(500).json({ success: false, error: error.message });
        }
      });
    }

    /**
     * Handles every Africa's Talking Voice callback hit for this node's webhook path:
     *  - call just connected (outbound we originated, or a brand new inbound call)
     *  - caller entered digits (routed to whichever node is currently "waiting")
     *  - call ended (cleanup)
     * In every "keep going" case we hold `res` open in pendingVoiceResponses and let
     * Send Message / End Flow finish the HTTP response with the right Voice XML.
     */
    async function handleVoiceWebhook(response, res, sessionManager, currentInitiationMode) {
      const serviceType = 'IVR';
      const phoneNumber = response.phoneNumber;
      const callerIdOrShortCode = config.callerId || config.shortCode;
      const sessionKey = createSessionKey(serviceType, phoneNumber, callerIdOrShortCode);

      // Call ended - clean up and acknowledge with an empty response.
      if (!response.isActive) {
        pendingVoiceResponses.delete(sessionKey);
        const existing = await sessionManager.getSession(sessionKey);
        if (existing?.exists) {
          await sessionManager.updateSession(sessionKey, { status: 'completed', endedAt: new Date().toISOString() });
        }
        res.set('Content-Type', 'text/xml');
        return res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
      }

      const sessionResult = await sessionManager.getSession(sessionKey);

      // No session yet - either a genuine inbound call, or an outbound pre-session expired.
      if (!sessionResult?.exists) {
        if (currentInitiationMode !== 'inbound') {
          res.set('Content-Type', 'text/xml');
          return res.send('<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="woman">Sorry, this session is no longer available.</Say><Hangup/></Response>');
        }

        const campaignId = flowId;
        await sessionManager.createSession(sessionKey, {
          sessionKey,
          campaignId,
          phoneNumber,
          serviceType,
          callerId: config.callerId || null,
          shortCode: config.shortCode || null,
          atSessionId: response.sessionId,
          status: 'active',
          source: 'webhook',
          initiationMode: 'inbound',
          currentWaitingNode: null,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString()
        }, config.sessionTimeout ? helpers.timeToSeconds(config.sessionTimeout) : 3600);

        pendingVoiceResponses.set(sessionKey, res);

        node.send({
          phoneNumber,
          campaignId,
          sessionKey,
          campaignType: 'voice',
          callerId: config.callerId || null,
          shortCode: config.shortCode || null,
          atSessionId: response.sessionId,
          _kumva: { campaignId, webhookPath, sessionKey, atSessionId: response.sessionId }
        });
        return; // HTTP response finalized downstream (Send Message)
      }

      const sessionData = sessionResult.data;

      // First webhook hit for a call WE originated (outbound) - link the real AT
      // sessionId and hand execution to Send Message.
      if (sessionData.status === 'initiating') {
        await sessionManager.updateSession(sessionKey, { status: 'active', atSessionId: response.sessionId });
        pendingVoiceResponses.set(sessionKey, res);

        node.send({
          phoneNumber,
          campaignId: sessionData.campaignId,
          sessionKey,
          campaignType: 'voice',
          contactData: sessionData.contactData || {},
          initialMessage: sessionData.initialMessage || '',
          credentials: sessionData.credentials,
          callerId: sessionData.callerId,
          shortCode: sessionData.shortCode,
          atSessionId: response.sessionId,
          _kumva: { campaignId: sessionData.campaignId, webhookPath, sessionKey, atSessionId: response.sessionId }
        });
        return;
      }

      // Subsequent hit (DTMF digits, recording, etc.) on an already-active session -
      // route to whichever node registered itself as "waiting" (same mechanism as SMS).
      const waitingNodeData = sessionData?.currentWaitingNode;
      if (waitingNodeData?.nodeId) {
        const targetNode = RED.nodes.getNode(waitingNodeData.nodeId);
        if (targetNode) {
          pendingVoiceResponses.set(sessionKey, res);
          targetNode.receive({
            response,
            isFromWebhook: true,
            campaignId: sessionData.campaignId,
            sessionKey,
            phoneNumber: sessionData.phoneNumber,
            callerId: sessionData.callerId,
            shortCode: sessionData.shortCode,
            atSessionId: response.sessionId
          });
          return;
        }
      }

      res.set('Content-Type', 'text/xml');
      return res.send('<?xml version="1.0" encoding="UTF-8"?><Response><Hangup/></Response>');
    }

    try {
      registerWebhookEndpoint(flowId);
      node.status({ fill: 'blue', shape: 'dot', text: `Listening: ${webhookPath}` });
    } catch (error) {
      node.error(error.message);
      node.status({ fill: 'red', shape: 'ring', text: 'Webhook error' });
    }

    node.on('input', async function(msg) {
      try {
        const phoneNumber = msg.phoneNumber || msg.contactData?.phone || msg.contactData?.[config.phoneColumn || 'phone'];
        const campaignId = flowId;

        if (!phoneNumber || !campaignId) {
          return node.error('Missing phoneNumber or campaignId');
        }

        node._currentCampaignId = campaignId;

        const effectiveCredentials = {
          username: node.credentials?.username || process.env.KUMVA_AT_USERNAME || process.env.AT_USERNAME || config.username || '',
          apiKey: node.credentials?.apiKey || process.env.KUMVA_AT_API_KEY || process.env.AT_API_KEY || config.apiKey || ''
        };

        const serviceType = campaignType === 'voice' ? 'IVR' : 'sms';
        const callerId = config.callerId || null;
        const shortCode = config.shortCode || null;
        const sessionKey = createSessionKey(serviceType, phoneNumber, callerId || shortCode || '');
        const sessionManager = node.context().global.get('sessionManager');
        const sessionTimeout = helpers.timeToSeconds(config.sessionTimeout || '3600s');

        // Outbound VOICE 
        // We only originate the call here. Execution continues once Africa's
        // Talking hits our webhook to say the call connected (inside handleVoiceWebhook).
        if (serviceType === 'IVR') {
          await sessionManager.createSession(sessionKey, {
            sessionKey,
            campaignId,
            phoneNumber,
            serviceType,
            callerId,
            shortCode,
            status: 'initiating',
            source: 'direct',
            initiationMode,
            contactData: msg.contactData || {},
            initialMessage: msg.initialMessage || '',
            credentials: effectiveCredentials,
            currentWaitingNode: null,
            createdAt: new Date().toISOString(),
            lastUpdated: new Date().toISOString()
          }, sessionTimeout);

          const atService = new AfricasTalkingService(effectiveCredentials);
          const callResult = await atService.makeCall(callerId, phoneNumber);
          console.log('call result: ', callResult)
          if (!callResult.success) {
            node.status({ fill: 'red', shape: 'ring', text: `Call failed: ${callResult.error || callResult.status}` });
            return node.error(`Failed to originate call: ${callResult.error || callResult.status}`);
          }

          node.status({ fill: 'blue', shape: 'dot', text: `Calling ${phoneNumber}...` });
          return;
        }

        // SMS
        await sessionManager.createSession(sessionKey, {
          sessionKey,
          campaignId,
          phoneNumber,
          serviceType,
          callerId,
          shortCode,
          status: 'active',
          source: 'direct',
          initiationMode,
          currentWaitingNode: null,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString()
        }, sessionTimeout);

        const campaignData = {
          campaignId,
          phoneNumber,
          campaignType,
          initiationMode,
          contactData: msg.contactData || {},
          initialMessage: msg.initialMessage || '',
          credentials: effectiveCredentials,
          shortCode,
          callerId,
          sessionTimeout,
          sessionKey
        };

        const outputMsg = {
          ...msg,
          campaignId,
          phoneNumber,
          callerId,
          shortCode,
          campaignData,
          sessionKey,
          initiationMode,
          credentials: campaignData.credentials,
        };
        node.status({ fill: 'green', shape: 'dot', text: `Campaign: ${campaignId}` });
        node.send(outputMsg);
      } catch (error) {
        node.error(`StartCampaign: ${error.message}`);
        node.status({ fill: 'red', shape: 'ring', text: 'Error' });
      }
    });

    node.on('close', (done) => {
      done();
    });
  }

  RED.nodes.registerType('kumva-start-campaign', KumvaStartCampaignNode, {
    credentials: {
      username: { type: 'text' },
      apiKey: { type: 'password' }
    }
  });
};